/* PLOTR creative engines. Original vector geometry; no raster in exported artwork. */
const creativeDefaults={
 modules:{motif:'orbits',columns:5,rows:6,lines:24,gap:7,offset:65,rotation:0,variation:55,turn:12},
 ribbons:{mode:'organic',count:9,lines:18,width:24,bend:28,frequency:1.4,angle:25,variation:60}
};
const creativeSpecs={
 modules:[['columns','Colonnes',1,16,1],['rows','Rangées',1,20,1],['lines','Traits par module',4,48,1],['gap','Espace entre modules (%)',0,45,1],['offset','Décentrage (%)',0,90,1],['rotation','Rotation (°)',-180,180,1],['variation','Variation entre cellules (%)',0,100,1],['turn','Torsion des carrés (°)',-35,35,1]],
 ribbons:[['count','Nombre de rubans',2,20,1],['lines','Traits par ruban',4,40,1],['width','Largeur (mm)',5,65,1],['bend','Amplitude des plis (mm)',0,55,1],['frequency','Fréquence des plis',.3,3,.1],['angle','Orientation (°)',-90,90,1],['variation','Variation des volumes (%)',0,100,1]]
};
function choice(id,label,options,value){return `<label>${label}<select id="${id}">${options.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></label>`}
const motifOptions=[['orbits','Cercles décentrés'],['fans','Éventails'],['spirals','Carrés tournoyants'],['maze','Méandres'],['circuits','Circuits'],['mix','Mélange de modules']];
function creativeControlsHTML(){const p=s.params;if(s.engine==='op')return choice('mode','Motif',[['wave','Vagues déformées'],['angular','Plis angulaires'],['rings','Anneaux concentriques']],p.mode)+choice('orientation','Orientation',[['horizontal','Horizontale'],['vertical','Verticale']],p.orientation)+'<label class="check"><input id="noCross" type="checkbox" '+(p.noCross?'checked':'')+'> Préserver un espace entre les lignes</label>';
 if(s.engine==='modules')return choice('moduleMotif','Module',motifOptions,p.motif);
 if(s.engine==='ribbons')return choice('ribbonMode','Construction',[['organic','Rubans organiques'],['angular','Plis angulaires']],p.mode)+'<p class="tip">Les rubans du premier plan occultent réellement les tracés derrière eux. Aucun remplissage ni masque SVG.</p>';
 return ''}
function bindCreativeControls(){for(const [id,key]of [['orientation','orientation'],['moduleMotif','motif'],['ribbonMode','mode'],['typeTexture','texture'],['typeMotif','motif']])if($(id))$(id).onchange=e=>{s.params[key]=e.target.value;if(id==='typeTexture'&&s.params.texture!=='outline'&&s.params.font==='mono'){s.params.font='archivo';controls()}schedule()};if($('noCross'))$('noCross').onchange=e=>{s.params.noCross=e.target.checked;schedule()};document.querySelectorAll('[data-type-preset]').forEach(el=>el.onclick=()=>{pause();Object.assign(s.params,{layout:'compose',font:'archivo',text:'PLAY\nTIME',size:38,y:20,align:'center',amplitude:0,texture:el.dataset.typePreset,textureSize:5,tracking:1});controls();render()});}
function generateOptical(p,colors){const [w,h]=dims,m=s.margin,vertical=p.orientation==='vertical',W=(vertical?h:w)-2*m,H=(vertical?w:h)-2*m,N=p.density,steps=p.mode==='angular'?p.samples:Math.max(80,Math.ceil(W/Math.max(.3,p.sampleStep))),map=(x,y)=>vertical?[y,x]:[x,y];
 if(p.mode==='rings'){for(let i=0;i<N;i++){const t=i/(N-1),pts=[];for(let j=0;j<=360;j++){const a=j/360*Math.PI*2,rad=3+t*Math.min(w,h)*.57+Math.sin(a*p.frequency+phase+t*8)*p.amplitude*t*.35;pts.push([w/2+Math.cos(a)*rad,h/2+Math.sin(a)*rad])}add(pts,i%colors)}return}
 const all=Array.from({length:N},()=>[]),noise=noiseFactory(s.seed),gap=H/(N-1)*.12;
 for(let j=0;j<=steps;j++){const u=j/steps,x=m+u*W,values=[];for(let i=0;i<N;i++){const t=i/(N-1),base=m+t*H;let delta=Math.sin(u*Math.PI*p.frequency+phase+t*4)*p.amplitude*Math.sin(Math.PI*t);if(p.mode==='angular')delta=noise(u*p.frequency+phase*.1,t*2)*p.amplitude*2*Math.sin(Math.PI*t);values.push(base+delta)}
 if(p.noCross){values[0]=m;for(let i=1;i<N;i++)values[i]=Math.max(values[i],values[i-1]+gap);values[N-1]=m+H;for(let i=N-2;i>=0;i--)values[i]=Math.min(values[i],values[i+1]-gap)}
 values.forEach((y,i)=>all[i].push(map(x,y)))}all.forEach((pts,i)=>add(pts,i%colors));}
// Unit motifs are reusable for grids and for typography. Every returned item is a polyline.
function moduleLines(motif,count,offset,turn,rng){const out=[],circle=(cx,cy,r)=>Array.from({length:65},(_,j)=>[cx+Math.cos(j/64*Math.PI*2)*r,cy+Math.sin(j/64*Math.PI*2)*r]);if(motif==='mix')motif=motifOptions[Math.floor(rng()*5)][0];
 if(motif==='orbits')for(let k=0;k<count;k++){const t=(k+1)/count,rad=.48*t;out.push(circle((.48-rad)*offset,0,rad))}
 if(motif==='spirals'){let q=[[-.48,-.48],[.48,-.48],[.48,.48],[-.48,.48]];for(let k=0;k<count;k++){out.push([...q,q[0]]);const t=Math.min(.45,Math.abs(turn)/90);q=q.map((a,i)=>{const b=q[(i+(turn<0?3:1))%4];return[a[0]*(1-t)+b[0]*t,a[1]*(1-t)+b[1]*t]})}}
 if(motif==='fans'){const center=[offset*.35,offset*.22];for(let k=0;k<count;k++){const t=k/count;for(let side=0;side<4;side++){const edges=[[-.5+t,-.5],[.5,-.5+t],[.5-t,.5],[-.5,.5-t]];out.push([edges[side],center])}}}
 if(motif==='maze')for(let k=0;k<Math.max(2,Math.floor(count/3));k++){const y=-.45+k/Math.max(1,Math.floor(count/3)-1)*.9,pts=[];for(let j=0;j<=12;j++){const x=-.48+j/12*.96;pts.push([x,y+(j%4<2?-.025:.025)])}out.push(pts)}
 if(motif==='circuits'){for(let k=0;k<Math.max(2,Math.floor(count/4));k++){const y=-.4+k/Math.max(1,Math.floor(count/4)-1)*.8;out.push([[-.48,y],[-.15,y],[-.15,y+.1],[.25,y+.1],[.25,y],[.48,y]])}out.push(circle(0,0,.12))}return out}
function generateModules(p,colors){const [w,h]=dims,m=s.margin,cw=(w-2*m)/p.columns,ch=(h-2*m)/p.rows,r=random(s.seed);for(let row=0;row<p.rows;row++)for(let col=0;col<p.columns;col++){const cx=m+(col+.5)*cw,cy=m+(row+.5)*ch,size=Math.min(cw,ch)*(1-p.gap/100),a=(p.rotation+(r()-.5)*360*p.variation/100)*Math.PI/180,co=Math.cos(a),si=Math.sin(a);for(const line of moduleLines(p.motif,Math.max(3,Math.round(p.lines)),p.offset/100,p.turn,r))add(line.map(([x,y])=>[cx+(x*co-y*si)*size,cy+(x*si+y*co)*size]),(row+col)%colors)}}
// Subtract polygon interiors geometrically, splitting segments at all boundary intersections.
function polygonBounds(poly){const xs=poly.map(v=>v[0]),ys=poly.map(v=>v[1]);return[Math.min(...xs),Math.min(...ys),Math.max(...xs),Math.max(...ys)]}
function insidePolygon(pt,poly){let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>pt[1])!==(b[1]>pt[1])&&pt[0]<(b[0]-a[0])*(pt[1]-a[1])/(b[1]-a[1])+a[0])inside=!inside}return inside}
function polygonClipLine(line,polygons,keepInside=false){const result=[];let part=[];const flush=()=>{if(part.length>1)result.push(part);part=[]};for(let j=1;j<line.length;j++){const a=line[j-1],b=line[j],dx=b[0]-a[0],dy=b[1]-a[1],cuts=[0,1];const candidates=polygons.filter(o=>Math.max(a[0],b[0])>=o.box[0]&&Math.min(a[0],b[0])<=o.box[2]&&Math.max(a[1],b[1])>=o.box[1]&&Math.min(a[1],b[1])<=o.box[3]);for(const o of candidates)for(let k=0;k<o.poly.length;k++){const c=o.poly[k],d=o.poly[(k+1)%o.poly.length],ex=d[0]-c[0],ey=d[1]-c[1],den=dx*ey-dy*ex;if(Math.abs(den)<1e-10)continue;const t=((c[0]-a[0])*ey-(c[1]-a[1])*ex)/den,u=((c[0]-a[0])*dy-(c[1]-a[1])*dx)/den;if(t>1e-8&&t<1-1e-8&&u>=0&&u<=1)cuts.push(t)}cuts.sort((a,b)=>a-b);for(let k=1;k<cuts.length;k++){const lo=cuts[k-1],hi=cuts[k];if(hi-lo<1e-9)continue;const mid=[a[0]+dx*(lo+hi)/2,a[1]+dy*(lo+hi)/2];let inside=false;if(keepInside){for(const o of candidates)if(insidePolygon(mid,o.poly))inside=!inside}else inside=candidates.some(o=>insidePolygon(mid,o.poly));if(inside===keepInside){const start=[a[0]+dx*lo,a[1]+dy*lo],end=[a[0]+dx*hi,a[1]+dy*hi];if(part.length&&dist(part.at(-1),start)>1e-5)flush();if(!part.length)part.push(start);part.push(end)}else flush()}}flush();return result}
function generateRibbons(p,colors){const [w,h]=dims,m=s.margin,W=w-2*m,H=h-2*m,r=random(s.seed),occluders=[];for(let k=0;k<p.count;k++){const cx=m+r()*W,cy=m+r()*H,a=(p.angle+(r()-.5)*150*p.variation/100)*Math.PI/180,co=Math.cos(a),si=Math.sin(a),len=Math.hypot(W,H)*1.3,phase0=r()*6.28,amp=p.bend*(.4+r()*.6),width=p.width*(.6+r()*.8),steps=p.mode==='angular'?8:80;
 const at=(t,v)=>{const x=(t-.5)*len,y=Math.sin(t*Math.PI*2*p.frequency+phase0)*amp+v*width*(.55+.45*Math.sin(t*Math.PI));return[cx+x*co-y*si,cy+x*si+y*co]},edge1=[],edge2=[];for(let j=0;j<=steps;j++){edge1.push(at(j/steps,-.5));edge2.push(at(j/steps,.5))}const poly=[...edge1,...edge2.reverse()];for(let i=0;i<p.lines;i++){const line=Array.from({length:steps+1},(_,j)=>at(j/steps,-.5+i/(p.lines-1)));for(const visible of polygonClipLine(line,occluders))add(visible,k%colors)}occluders.push({poly,box:polygonBounds(poly)});}}
// Typography texture: clip motifs to actual font outlines with an even-odd rule (counters stay empty).
function textureGeometry(geometry,p,layer=0){if(!geometry.length)return;const polygons=geometry.filter(l=>l.length>2&&dist(l[0],l.at(-1))<.01).map(poly=>({poly,box:polygonBounds(poly)}));if(!polygons.length){for(const pts of geometry)add(pts,layer);return}const all=geometry.flat(),box=polygonBounds(all);box[0]=Math.max(s.margin,box[0]);box[1]=Math.max(s.margin,box[1]);box[2]=Math.min(dims[0]-s.margin,box[2]);box[3]=Math.min(dims[1]-s.margin,box[3]);const cell=p.textureSize||5,r=random(s.seed),motif=p.motif||'mix';if(p.texture==='echo'){echoGeometry(polygons,box,p,layer);return}
 for(let y=box[1];y<box[3];y+=cell)for(let x=box[0];x<box[2];x+=cell){const cx=x+cell/2,cy=y+cell/2;const local=polygons.filter(o=>o.box[2]>=x&&o.box[0]<=x+cell&&o.box[3]>=y&&o.box[1]<=y+cell);if(!local.length)continue;const angle=Math.floor(r()*4)*Math.PI/2,co=Math.cos(angle),si=Math.sin(angle);for(const line of moduleLines(motif,Math.max(3,Math.round((p.textureLines||10))),.75,18,r)){const points=line.map(([a,b])=>[cx+(a*co-b*si)*cell,cy+(a*si+b*co)*cell]);for(const clipped of polygonClipLine(points,local,true))add(clipped,layer)}}if(p.textureOutline)for(const line of geometry)add(line,layer)}
// Signed chamfer distance contours: the text is revealed by nested lines, including its surroundings.
function echoGeometry(polygons,box,p,layer){const [w,h]=dims,m=s.margin,step=1.1,nx=Math.ceil((w-2*m)/step)+1,ny=Math.ceil((h-2*m)/step)+1,mask=new Uint8Array(nx*ny),d=new Float32Array(nx*ny).fill(1e6);for(let y=0;y<ny;y++){const yy=m+y*step,cuts=[];for(const o of polygons)for(let i=0;i<o.poly.length;i++){const a=o.poly[i],b=o.poly[(i+1)%o.poly.length];if((a[1]>yy)!==(b[1]>yy))cuts.push(a[0]+(yy-a[1])*(b[0]-a[0])/(b[1]-a[1]))}cuts.sort((a,b)=>a-b);for(let k=0;k+1<cuts.length;k+=2)for(let x=Math.max(0,Math.ceil((cuts[k]-m)/step));x<nx&&m+x*step<cuts[k+1];x++)mask[y*nx+x]=1}
 for(let y=1;y<ny-1;y++)for(let x=1;x<nx-1;x++){const i=y*nx+x;if(mask[i]!==mask[i-1]||mask[i]!==mask[i+1]||mask[i]!==mask[i-nx]||mask[i]!==mask[i+nx])d[i]=0}
 for(let y=0;y<ny;y++)for(let x=0;x<nx;x++){const i=y*nx+x;if(x)d[i]=Math.min(d[i],d[i-1]+1);if(y)d[i]=Math.min(d[i],d[i-nx]+1);if(x&&y)d[i]=Math.min(d[i],d[i-nx-1]+Math.SQRT2);if(y&&x<nx-1)d[i]=Math.min(d[i],d[i-nx+1]+Math.SQRT2)}for(let y=ny-1;y>=0;y--)for(let x=nx-1;x>=0;x--){const i=y*nx+x;if(x<nx-1)d[i]=Math.min(d[i],d[i+1]+1);if(y<ny-1)d[i]=Math.min(d[i],d[i+nx]+1);if(x<nx-1&&y<ny-1)d[i]=Math.min(d[i],d[i+nx+1]+Math.SQRT2);if(x&&y<ny-1)d[i]=Math.min(d[i],d[i+nx-1]+Math.SQRT2)}for(let i=0;i<d.length;i++)d[i]*=step*(mask[i]?-1:1);
 const spacing=Math.max(.8,p.textureSize/3),segments=[];for(let level=-20;level<=Math.max(w,h);level+=spacing){let any=false;for(let y=0;y<ny-1;y++)for(let x=0;x<nx-1;x++){const ids=[y*nx+x,y*nx+x+1,(y+1)*nx+x+1,(y+1)*nx+x],corners=[[x,y],[x+1,y],[x+1,y+1],[x,y+1]],hits=[];for(let k=0;k<4;k++){const j=(k+1)%4,a=d[ids[k]],b=d[ids[j]];if((a<level)!==(b<level)){const t=(level-a)/(b-a);hits.push([m+(corners[k][0]+(corners[j][0]-corners[k][0])*t)*step,m+(corners[k][1]+(corners[j][1]-corners[k][1])*t)*step])}}for(let k=0;k+1<hits.length;k+=2){segments.push([hits[k],hits[k+1]]);any=true}}if(!any&&level>30)break}for(const line of joinSegments(segments))add(line,layer)}
let typeRaw=[];
function typeAdd(points,layer){typeRaw.push({points,layer});add(points,layer)}
function applyTypeTexture(){if(s.engine!=='type'||s.params.texture==='outline')return;paths=[];textureGeometry(typeRaw.map(p=>p.points),s.params,0)}
function typeTextureHTML(){const p=s.params;return `<div class="preset-row"><button data-type-preset="motifs">Lettres matières</button><button data-type-preset="echo">Texte & échos</button></div><div class="section-label">MATIÈRE TYPOGRAPHIQUE</div>${choice('typeTexture','Construction des lettres',[['outline','Contours classiques'],['motifs','Lettres en modules'],['echo','Échos autour du texte']],p.texture)}${choice('typeMotif','Motifs dans les lettres',motifOptions,p.motif)}${numberControl('textureSize','Taille des modules / échos (mm)',p.textureSize,2,18,.5,'type')}${numberControl('textureLines','Détail des modules',p.textureLines,3,24,1,'type')}<label class="check"><input id="textureOutline" type="checkbox" ${p.textureOutline?'checked':''}> Ajouter le contour des lettres</label><p class="tip">Utilisez Archivo Black ou Bebas et un grand corps pour les motifs. Échos fonctionne mieux en texte composé, sans ondulation.</p>`}
function randomizeCreative(r){if(s.engine==='modules')Object.assign(s.params,{motif:motifOptions[Math.floor(r()*motifOptions.length)][0],offset:30+Math.round(r()*60),rotation:Math.round(r()*180),variation:Math.round(r()*100)});if(s.engine==='ribbons')Object.assign(s.params,{angle:Math.round((r()-.5)*120),bend:12+Math.round(r()*35),frequency:+(.5+r()*1.5).toFixed(1)})}

function joinSegments(segments){const key=p=>p.map(v=>v.toFixed(5)).join(','),adj=new Map(),used=new Set(),result=[];segments.forEach((seg,i)=>seg.forEach(p=>{const k=key(p);if(!adj.has(k))adj.set(k,[]);adj.get(k).push(i)}));for(let i=0;i<segments.length;i++){if(used.has(i))continue;used.add(i);const line=[...segments[i]];for(let end=0;end<2;end++){if(end)line.reverse();while(true){const p=line.at(-1),next=(adj.get(key(p))||[]).find(j=>!used.has(j));if(next===undefined)break;used.add(next);const seg=segments[next];line.push(key(seg[0])===key(p)?seg[1]:seg[0])}}result.push(line)}return result}
